import{_ as i,c as t,o as a,ag as n}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"nPlyr","text":"不止于播放的视频播放器","tagline":"基于 AVFoundation 打造的 macOS 与 iOS 原生播放器。内置嗅探器抓取任意网站的视频流，还能运行小程序。","image":{"src":"/hero-illustration.png","alt":"nPlyr"},"actions":[{"theme":"brand","text":"开始使用","link":"/zh-CN/guide/installation"},{"theme":"alt","text":"小程序","link":"/zh-CN/guide/miniapps"}]},"features":[{"icon":{"light":"/icons/layers.svg","dark":"/icons/layers-dark.svg","alt":"播放器","width":"24","height":"24"},"title":"原生播放器","details":"macOS 与 iOS 共用一套基于 AVFoundation（AVPlayer）的播放内核。支持 HLS/m3u8、MP4、FLV、TS 等格式，并具备字幕、音轨、倍速、画中画与 AirPlay。","link":"/zh-CN/guide/player","linkText":"了解更多"},{"icon":{"light":"/icons/zap.svg","dark":"/icons/zap-dark.svg","alt":"嗅探器","width":"24","height":"24"},"title":"内置嗅探器","details":"一个 Chrome 风格的多标签浏览器，会向每个页面注入媒体探测脚本，将 m3u8/mp4/flv/ts 直链及其请求头汇总到一个抽屉中。","link":"/zh-CN/guide/browser","linkText":"工作原理"},{"icon":{"light":"/icons/sparkles.svg","dark":"/icons/sparkles-dark.svg","alt":"小程序","width":"24","height":"24"},"title":"小程序运行时","details":"原生运行与 hikerView 兼容的小程序与规则——同一套规则 DSL 与 fy_bridge_app 契约，在 Apple 平台重新实现。浏览社区资源目录。","link":"/zh-CN/guide/miniapps","linkText":"探索运行时"},{"icon":{"light":"/icons/camera.svg","dark":"/icons/camera-dark.svg","alt":"下载","width":"24","height":"24"},"title":"下载与边下边播","details":"将 HLS 播放列表下载为 MP4，或在文件仍在下载时即可开始观看（边下边播）。支持多清晰度与字幕下载。","link":"/zh-CN/guide/downloads","linkText":"下载指南"},{"icon":{"light":"/icons/eye.svg","dark":"/icons/eye-dark.svg","alt":"媒体库","width":"24","height":"24"},"title":"媒体库","details":"观看历史、书签与下载内容统一收纳在一个可搜索的媒体库中，并在你的 Mac 与 iPhone 之间同步。","link":"/zh-CN/guide/downloads","linkText":"打开媒体库"},{"icon":{"light":"/icons/frame.svg","dark":"/icons/frame-dark.svg","alt":"主题","width":"24","height":"24"},"title":"主题与 25 种语言","details":"在内置主题之间切换，或自定义属于你的主题。整个界面已本地化为 25 种语言，并在两个平台上跟随系统外观。","link":"/zh-CN/guide/settings","linkText":"个性化"}],"floatingCards":["原生 AVFoundation 内核","无多余负担","嗅探器 + 浏览器","小程序运行时"],"sections":{"featuresTitle":"核心功能","featuresSubtitle":"在 Apple 平台上播放、抓取与整理视频所需的一切","categoriesTitle":"你能做什么","categoriesSubtitle":"一个应用，集播放器、浏览器与小程序运行时于一体","howTitle":"工作原理","howSubtitle":"开箱即用、协同工作的三大部分","faqTitle":"常见问题","faqSubtitle":"面向 macOS 与 iOS 用户的快速解答"},"openMarketplace":"浏览小程序","cta":{"title":"准备好播放任何内容了吗？","description":"下载 nPlyr，把任意网页变成可播放的视频流——原生运行于你的 Mac 与 iPhone，由 AVFoundation 驱动。","primary":"开始使用","primaryLink":"/guide/installation","secondary":"使用指南","secondaryLink":"/guide/player"},"categories":[{"name":"观看","badge":"PL","desc":"播放本地文件、URL 与流","color":"#ef6400"},{"name":"抓取","badge":"SN","desc":"从网页嗅探直链","color":"#2563eb"},{"name":"扩展","badge":"MP","desc":"运行 hikerView 小程序","color":"#059669"},{"name":"保存","badge":"DL","desc":"下载并整理媒体","color":"#7c3aed"},{"name":"同步","badge":"LB","desc":"跨设备媒体库","color":"#d97706"},{"name":"个性化","badge":"TH","desc":"主题与 25 种语言","color":"#0891b2"}],"steps":[{"num":"01","title":"安装并启动","desc":"从 Mac App Store 获取 nPlyr，或侧载 iOS 版本，然后从 Dock 或主屏幕启动。"},{"num":"02","title":"打开一个视频","desc":"将文件拖入主播放器，或粘贴一个链接，也可以使用内置浏览器查找视频流。"},{"num":"03","title":"抓取与扩展","desc":"一键嗅探直链，或打开社区小程序，浏览整个视频源。"}],"faqs":[{"question":"nPlyr 免费吗？","answer":"nPlyr 在 App Store 上是付费应用。免费层级可试用核心播放器与有限数量的小程序；解锁后取消小程序数量限制。没有账号体系，也没有遥测。"},{"question":"支持哪些平台？","answer":"nPlyr 支持 macOS 14 Sonoma 及以上（针对 Apple Silicon 优化，同时支持 Intel），以及 iOS / iPadOS 16 及以上。两个平台共用同一套播放内核。"},{"question":"它使用了 ffmpeg 或其他外部二进制吗？","answer":"没有。播放与重封装内核完全基于 Apple 的 AVFoundation（AVPlayer）构建。这让应用保持轻量、沙盒友好并符合 App Store 规范。"},{"question":"支持哪些视频格式？","answer":"由于依赖 AVFoundation，nPlyr 可播放操作系统原生解码的一切格式——HLS（m3u8）、分片 MP4、MP4、MOV、M4V，以及 AVPlayer 可读取的容器。对于 HLS，下载与重封装为 MP4 均在应用内完成。"},{"question":"什么是小程序，它们安全吗？","answer":"小程序是 hikerView 兼容的规则，让 nPlyr 通过沙盒化的 JavaScript 引擎浏览并解析第三方视频源。它们由社区提供。具体哪些 Java/Rhino 行为被支持、哪些不被支持，请参阅兼容性页面。"},{"question":"嗅探器在所有网站都能用吗？","answer":"嗅探器会捕获页面发起的媒体请求（fetch/XHR/video.src/MediaSource）。使用专有播放器或重度 DRM 包裹视频流的站点可能不会暴露直链。对于这类源，小程序运行时是更可靠的路径。"}]},"headers":[],"relativePath":"zh-CN/index.md","filePath":"zh-CN/index.md","lastUpdated":1791311600000}'),o={name:"zh-CN/index.md"};function l(r,e,s,d,c,g){return a(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="nplyr-是一个三合一的媒体应用" tabindex="-1">nPlyr 是一个三合一的媒体应用 <a class="header-anchor" href="#nplyr-是一个三合一的媒体应用" aria-label="Permalink to &quot;nPlyr 是一个三合一的媒体应用&quot;">​</a></h2><p>与单纯的播放器不同，nPlyr 在一套共享规则引擎之上，融合了<strong>原生播放器</strong>、<strong>媒体嗅探浏览器</strong>与<strong>hikerView 兼容的小程序运行时</strong>。你可以观看文件、从网页抓取视频流，或打开社区小程序让它帮你浏览整个视频源——全程无需离开应用。</p><ul><li><strong>播放内核</strong>——macOS 与 iOS 均为 <code>AVPlayer</code>，零外部二进制。</li><li><strong>嗅探器</strong>——一个 <code>WKWebView</code> 容器，注入 JS 拦截媒体请求，汇总直链 + 请求头。</li><li><strong>小程序运行时</strong>——对 hikerView 桥接（<code>fy_bridge_app</code>）与规则 DSL 的原生重实现，因此现有社区规则可直接运行。</li></ul><blockquote><p>为 Apple 平台而生。没有 Electron，没有遥测。</p></blockquote>',4)])])}const u=i(o,[["render",l]]);export{p as __pageData,u as default};
